/** Convenience lookup helper. */
export function getPolicyEnrichment(registrationNo: string | null | undefined): PolicyEnrichment | null {
  if (!registrationNo) return null;
  const key = registrationNo.trim().toUpperCase();
  return POLICY_ENRICHMENT_BY_REG_NO[key] ?? null;
}
